($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 1014873, $f$Cold Embrace$f$, ARRAY[$f$Shadowofdarkness22$f$]::text[], ARRAY[$f$Dishonored (Video Game)$f$]::text[], NULL, ARRAY[]::text[], $f$He owed a lot to the Outsider, even if he never asked for his help in the first place.$f$, 1326, 1, 1, true, 1, false, $f$2019-07-07T13:21:10.848+00:00$f$, $f$2019-07-07T13:21:10.950+00:00$f$, $f$2013-10-23T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
