($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 3275807, $f$Taking Licenses$f$, ARRAY[$f$SathInflection$f$]::text[], ARRAY[$f$The Hobbit (Jackson Movies)$f$]::text[], NULL, ARRAY[]::text[], $f$Bard is told that the only way he can renew his barge license is by having sex with Thranduil.$f$, 814, 1, 1, true, 5, false, $f$2019-06-10T22:01:21.184+00:00$f$, $f$2019-06-10T22:01:21.541+00:00$f$, $f$2015-02-02T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 3277007, $f$Облачное море$f$, ARRAY[$f$Mariuelle$f$]::text[], ARRAY[$f$Gentleman Bastard Sequence - Scott Lynch$f$]::text[], NULL, ARRAY[]::text[], NULL, NULL, 2, NULL, false, -1, false, $f$2018-01-12T04:25:25.227+00:00$f$, $f$2018-01-12T04:25:25.230+00:00$f$, $f$2015-02-02T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 3280445, $f$Had We But World Enough and Time$f$, ARRAY[$f$oxymoronic$f$]::text[], ARRAY[$f$The Hobbit - All Media Types$f$, $f$The Hobbit (Jackson Movies)$f$]::text[], NULL, ARRAY[]::text[], $f$Many years have passed since they last met, and yet Bard still cannot help but look towards the great forests above the lake, wonder whether the Wood King will one day call upon him again; but it is not until Legolas' return that he realises Thranduil's long silence may have a more sinister cause.$f$, 13537, 1, 1, true, 5, false, $f$2019-08-27T01:34:46.264+00:00$f$, $f$2019-08-27T01:34:46.309+00:00$f$, $f$2015-02-03T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 3304583, $f$Tie$f$, ARRAY[$f$yeaka$f$]::text[], ARRAY[$f$The Hobbit - All Media Types$f$, $f$TOLKIEN J. R. R. - Works & Related Fandoms$f$]::text[], NULL, ARRAY[]::text[], $f$Bard offers himself to the Elf King in exchange for aid.$f$, 6935, 1, 1, true, 3, false, $f$2019-08-23T11:17:11.410+00:00$f$, $f$2019-08-23T11:17:11.443+00:00$f$, $f$2015-02-07T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 3317030, $f$A Terrible Idea$f$, ARRAY[$f$Sixthlight$f$, $f$KD reads (KDHeart)$f$]::text[], ARRAY[$f$Rivers of London - Ben Aaronovitch$f$]::text[], NULL, ARRAY[]::text[], $f$The trouble with having spectacular and possibly very slightly kinky sex with your boss because he’s caught you ogling him after work-related sports practice is that however well it goes, there’s no easy way to suggest a repeat.$f$, 2733, 1, 1, true, 5, false, $f$2019-06-10T08:46:29.504+00:00$f$, $f$2019-06-10T08:46:29.802+00:00$f$, $f$2015-02-09T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 3318284, $f$The Maimed King$f$, ARRAY[$f$Sath$f$]::text[], ARRAY[$f$The Hobbit (Jackson Movies)$f$]::text[], NULL, ARRAY[]::text[], $f$So, this chapter is essentially 2,000 words of sex. If that's what you've been hankering for, great! If not, you can skip this chapter without missing anything important.$f$, 25812, 11, 11, true, 5, false, $f$2019-08-22T21:52:44.155+00:00$f$, $f$2019-08-22T21:52:44.290+00:00$f$, $f$2015-12-31T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 3321914, $f$And in my lady's chamber$f$, ARRAY[$f$destiencestiel (orphan_account)$f$]::text[], ARRAY[$f$The Hobbit - All Media Types$f$, $f$The Hobbit - J. R. R. Tolkien$f$, $f$The Hobbit (Jackson Movies)$f$]::text[], NULL, ARRAY[]::text[], $f$Bard has to stay the nigt after a meeting in the Woodland Realm. She gets offered the spare bed in Queen Tharandiel's room, Tharandiel decides to show her feelings to Bard and Bard is delighted.$f$, 2828, 5, 5, true, -1, false, $f$2019-08-23T11:32:20.267+00:00$f$, $f$2019-08-23T11:32:20.299+00:00$f$, $f$2015-02-09T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
